import {ThemeSelect} from './Theme';
import {useEffect, useRef, useState, type FormEvent, type ReactNode} from 'react';
import {ArrowLeft, ArrowRight, CalendarDays, Check, ClipboardCheck, Download, FolderOpen, HardDrive, Layers, LayoutDashboard, LockKeyhole, MessageSquare, Plus, Printer, Search, TrendingUp, Upload, Wallet, X} from 'lucide-react';
import LegacyApp from './App';
import {Help} from './Help';
import {ReadyForm, Required} from './ReadyForm';
import {ProfileView} from './ProfileView';
import {useModalScrollLock} from './useModalScrollLock';
import {materials, MaterialCredit, type Material} from './materials';
import {budgetTotals, conceptTotal, distributeDaily, findProjects, freezeProject, parseCatalog, progressAt, projectMetrics, projectSeries, recordExpense, recordProgress, saveConcept, scheduleProject, validateProjects} from './project-core.mjs';
import './works.css';

type Concept = {materialId?:string;id:string;code:string;description:string;unit:string;quantity:number;price:number;pricing:string;indirect:number;profit:number;charges:number;start:string;end:string;daily?:{date:string;quantity:number}[]};
type Progress = {id:string;conceptId:string;start:string;end:string;percent:number};
type Expense = {id:string;conceptId:string;date:string;label:string;amount:number;iva:number;quantity:number;unit:string;category:string};
type Project = {id:string;name:string;type:string;dimensions:string;start:string;end:string;iva:number|null;concepts:Concept[];progress:Progress[];expenses:Expense[];notes:string[];reminder?:{date:string;text:string};baseline?:{approvedAt:string;subtotal:number}};
type Page = 'summary'|'budget'|'schedule'|'progress'|'expenses'|'review';
const expenseCategories = ['Materiales','Mano de obra','Maquinaria','Subcontratos','Servicios','Gastos de oficina','Gastos de oficina de campo','Depreciación, mantenimiento y rentas','Indirectos','Otros gastos'];
const KEY = 'trazal-projects-v2';
const money = (n:number|null) => n===null?'Por definir':new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(n);
const num = (n:number,d=2) => new Intl.NumberFormat('es-MX',{maximumFractionDigits:d}).format(n);
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const day = (s:string) => !s?'Por definir':new Date(s+'T12:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'});
const id = () => crypto.randomUUID();
function download(name:string, content:string, type='application/json') {const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows:(string|number)[][]) {return '\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');}
function Heading({title,help}:{title:string;help:string}) {return <div className="title-with-help"><h2>{title}</h2><Help title={title}>{help}</Help></div>;}
function Blank({children}:{children:ReactNode}) {return <div className="works-empty"><FolderOpen size={30}/><p>{children}</p></div>;}
function Metric({label,value,help}:{label:string;value:string;help:string}) {return <div className="metric"><div className="title-with-help"><span>{label}</span><Help title={label}>{help}</Help></div><strong>{value}</strong></div>;}
const pages:{id:Page;label:string;icon:typeof Layers}[] = [
  {id:'summary',label:'Resumen',icon:LayoutDashboard},{id:'budget',label:'Catálogo y presupuesto',icon:Layers},
  {id:'schedule',label:'Programa de obra',icon:CalendarDays},{id:'progress',label:'Avance real',icon:ClipboardCheck},
  {id:'expenses',label:'Gastos y compras',icon:Wallet},{id:'review',label:'Acuerdos y reporte',icon:MessageSquare},
];

function Curve({project,cutoff}:{project:Project;cutoff:string}) {
  const series = projectSeries(project,cutoff);
  const [visible,setVisible] = useState({pv:true,ev:true,ac:true});
  const colors = {pv:'var(--curve-pv, #4687B5)',ev:'var(--curve-ev, #68716B)',ac:'var(--curve-ac, #C34F43)'};
  const labels = {pv:'Programa fijo',ev:'Avance real',ac:'Gasto real'};
  const width=900,height=290,left=76,right=25,top=20,bottom=45;
  const start=Date.parse(project.start), end=Date.parse(series.at(-1)!.date);
  const max=Math.max(1,...series.flatMap(s=>[s.pv,s.date<=cutoff?s.ev:0,s.date<=cutoff?s.ac:0]))*1.1;
  const x=(date:string)=>left+(Date.parse(date)-start)/Math.max(86400000,end-start)*(width-left-right);
  const y=(n:number)=>height-bottom-n/max*(height-top-bottom);
  return <div className="works-curve"><div className="chart-legend">{(['pv','ev','ac'] as const).map(key=><button key={key} aria-pressed={visible[key]} onClick={()=>setVisible({...visible,[key]:!visible[key]})}><i style={{background:colors[key],opacity:visible[key]?1:.25}}/>{labels[key]}</button>)}<span>MXN sin IVA</span></div>
    <svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Programa fijo azul, avance real gris y gasto real rojo, acumulados a la fecha de corte">
      {[0,.25,.5,.75,1].map(v=><g key={v}><line x1={left} x2={width-right} y1={y(max*v)} y2={y(max*v)} stroke="#e4e6de" strokeDasharray="3 4"/><text x={left-12} y={y(max*v)+5} textAnchor="end">{num(max*v/1000,0)} mil</text></g>)}
      {(['pv','ev','ac'] as const).map(key=>visible[key]&&<polyline key={key} points={series.filter(s=>key==='pv'||s.date<=cutoff).map(s=>`${x(s.date)},${y(s[key])}`).join(' ')} fill="none" stroke={colors[key]} strokeWidth="3" strokeDasharray={key==='pv'?'7 4':undefined}/>) }
      <line x1={x(cutoff)} x2={x(cutoff)} y1={top} y2={height-bottom} stroke="#9b9f91" strokeDasharray="4 4"/>
      {[0,.25,.5,.75,1].map(f=>{const d=new Date(start+(end-start)*f).toISOString().slice(0,10);return <text key={f} x={x(d)} y={height-10} textAnchor="middle">{day(d).replace(/ de /g,' ').replace(/ 20\d\d/,'')}</text>;})}
    </svg><p className="works-caption">Corte al {day(cutoff)} · Las capturas posteriores se muestran al cambiar la fecha.</p>
  </div>;
}

export default function Works() {
  const [projects,setProjects] = useState<Project[]>(()=>{try {return validateProjects(JSON.parse(localStorage.getItem(KEY)||'{"version":2,"projects":[]}')).projects;}catch{return [];}});
  const [profile,setProfile] = useState(()=>{try{const p=JSON.parse(localStorage.getItem('trazal-profile-v1')||'null');if(p&&typeof p.firstName==='string'&&p.firstName.trim()&&['lastName','email','phone','company'].every(k=>typeof p[k]==='string'))return p as {firstName:string;lastName:string;email:string;phone:string;company:string};}catch{/* Start with a local demo profile. */}return {firstName:'Joseph',lastName:'',email:'',phone:'',company:''};});
  const [profileOpen,setProfileOpen] = useState(false);
  const [selected,setSelected] = useState<string|null>(null);
  const [page,setPage] = useState<Page>('summary');
  const [cutoff,setCutoff] = useState(today);
  const [query,setQuery] = useState('');
  const [projectFilters,setProjectFilters] = useState({query:'',type:'',status:'',from:'',to:'',sort:'name'});
  const [showDates,setShowDates] = useState(false);
  const [modal,setModal] = useState<{kind:string;concept?:Concept}|null>(null);
  useModalScrollLock(!!modal);
  const [error,setError] = useState('');
  const [notice,setNotice] = useState('');
  const [saved,setSaved] = useState(true);
  const [pricing,setPricing] = useState('quoted');
  const [expenseCategory,setExpenseCategory] = useState('Todas');
  const [captureMode,setCaptureMode] = useState('percent');
  const [captureConcept,setCaptureConcept] = useState('');
  const [daily,setDaily] = useState<{date:string;quantity:number}[]>([]);
  const [dailyFrom,setDailyFrom] = useState(0);
  const dialog = useRef<HTMLDialogElement>(null);
  const restore = useRef<HTMLElement|null>(null);
  const backup = useRef<HTMLInputElement>(null);
  const project = projects.find(p=>p.id===selected);
  const visibleExpenses = (project?.expenses||[]).filter(e=>expenseCategory==='Todas'||e.category===expenseCategory);
  const expenseAtCut = visibleExpenses.filter(e=>e.date<=cutoff);
  const foundProjects = findProjects(projects,projectFilters) as Project[];
  const projectTypes = [...new Set(projects.map(p=>p.type))].sort((a,b)=>a.localeCompare(b,'es'));
  const filtering = !!(projectFilters.query.trim()||projectFilters.type||projectFilters.status||projectFilters.from||projectFilters.to);
  const invalidRange = !!(projectFilters.from&&projectFilters.to&&projectFilters.from>projectFilters.to);
  function filterWorks(key:keyof typeof projectFilters,value:string) {setProjectFilters(f=>({...f,[key]:value}));}
  function clearFilters() {setProjectFilters({query:'',type:'',status:'',from:'',to:'',sort:'name'});}
  useEffect(()=>{try{localStorage.setItem(KEY,JSON.stringify({version:2,projects}));setSaved(true);}catch{setSaved(false);}},[projects]);
  useEffect(()=>{if(modal) dialog.current?.showModal();else {dialog.current?.close();restore.current?.focus();}},[modal]);
  useEffect(()=>{if(notice){const timer=setTimeout(()=>setNotice(''),7000);return()=>clearTimeout(timer);}},[notice]);
  function open(kind:string,concept?:Concept) {restore.current=document.activeElement as HTMLElement;setError('');setModal({kind,concept});setPricing(concept?.pricing||'quoted');setCaptureMode('percent');setCaptureConcept(concept?.id||project?.concepts.find(c=>progressAt(project,c.id,'9999-12-31')<100)?.id||'');if(kind==='daily'&&concept){setDaily(structuredClone(concept.daily||[]));setDailyFrom(0);}}
  function pickMaterial(material:Material) {if(!project)return;let suffix=1;while(project.concepts.some(c=>c.code===`${material.code}-${String(suffix).padStart(3,'0')}`))suffix++;open('concept',{id:id(),code:`${material.code}-${String(suffix).padStart(3,'0')}`,description:material.name,unit:material.unit,quantity:1,price:0,pricing:'build',indirect:0,profit:0,charges:0,start:project.start,end:project.end,materialId:material.id});}
  function update(next:Project) {setProjects(list=>list.map(p=>p.id===next.id?next:p));}
  function go(next:Page) {setPage(next);setQuery('');window.scrollTo({top:0,behavior:'instant'});}
  function choose(p:Project) {setSelected(p.id);setCutoff(p.start||today());go('summary');}
  function exportAll() {download('Trazal-obras.json',JSON.stringify({version:2,projects},null,2));}
  async function restoreBackup(file:File) {try{if(file.size>5e6)throw new Error('El respaldo debe ser menor de 5 MB.');const restored=validateProjects(JSON.parse(await file.text())).projects as Project[];const copy=restored.map(p=>({...p,id:id(),name:p.name+' · recuperada'}));setProjects(p=>[...p,...copy]);setNotice(`${copy.length} obras recuperadas como copias.`);}catch(e){setNotice((e as Error).message);}}
  function submit(event:FormEvent<HTMLFormElement>) {
    event.preventDefault();const data=new FormData(event.currentTarget);const str=(name:string)=>String(data.get(name)||'').trim();const n=(name:string)=>Number(str(name));
    try {
      if(modal?.kind==='create') {
        const next:Project={id:id(),name:str('name'),type:str('type'),dimensions:str('dimensions'),start:'',end:'',iva:str('iva')===''?null:n('iva'),concepts:[],progress:[],expenses:[],notes:[]};
        validateProjects({version:2,projects:[next]});setProjects(list=>[...list,next]);choose(next);setPage('budget');setNotice('Obra creada. Agrega su catálogo de conceptos.');
      }
      if(project) {
        if(modal?.kind==='concept') {
          const c:Concept={id:modal.concept?.id||id(),code:str('code'),description:str('description'),unit:str('unit')||'lote',quantity:str('quantity')?n('quantity'):1,price:n('price'),pricing,indirect:n('indirect'),profit:n('profit'),charges:n('charges'),start:modal.concept?.start||project.start,end:modal.concept?.end||project.end,...(modal.concept?.materialId?{materialId:modal.concept.materialId}:{})};
          // Dates and quantities may change in draft: explicitly re-review its daily plan.
          if(modal.concept && c.start===modal.concept.start && c.end===modal.concept.end && c.quantity===modal.concept.quantity) c.daily=modal.concept.daily;
          update(saveConcept(project,c));setNotice('Concepto guardado en el presupuesto.');
        }
        if(modal?.kind==='catalog') {update(parseCatalog(project,str('catalog'),id));setNotice('Catálogo agregado. Revisa las fechas y el programa diario.');}
        if(modal?.kind==='schedule'){update(scheduleProject(project,str('start'),str('end')));setNotice('Fechas del programa guardadas.');}
        if(modal?.kind==='conceptDates'){const c=modal.concept!;update(saveConcept(project,{...c,start:str('start'),end:str('end'),daily:c.start===str('start')&&c.end===str('end')?c.daily:undefined}));setNotice('Fechas guardadas. Revisa la distribución diaria.');}
        if(modal?.kind==='tax') {const next={...project,iva:n('iva')};if(project.baseline)throw new Error('El presupuesto aprobado está bloqueado.');validateProjects({version:2,projects:[next]});update(next);}
        if(modal?.kind==='daily') {update(saveConcept(project,{...modal.concept!,daily}));setNotice('Distribución diaria guardada.');}
        if(modal?.kind==='freeze') {update(freezeProject(project));go('summary');setNotice('Programa fijado. Ya puedes registrar avance y gastos.');}
        if(modal?.kind==='progress') {
          const concept=project.concepts.find(c=>c.id===captureConcept);if(!concept)throw new Error('Selecciona un concepto pendiente.');
          const cumulative=captureMode==='percent'?n('value'):n('value')/concept.quantity*100;
          const entry={id:id(),conceptId:captureConcept,start:str('start'),end:str('end'),percent:cumulative};
          update(recordProgress(project,entry));setCutoff(entry.end);setNotice(cumulative===100?'Concepto terminado: 100 %. Se bloquean nuevas capturas.':'Avance acumulado registrado. La curva y los indicadores se actualizaron.');
        }
        if(modal?.kind==='expense') {
          const entry={id:id(),conceptId:str('concept'),date:str('date'),label:str('label'),amount:n('amount'),iva:n('iva'),quantity:n('quantity'),unit:str('unit'),category:str('category')};
          if(!Number.isFinite(entry.quantity)||entry.quantity<0)throw new Error('Revisa la cantidad comprada.');
          update(recordExpense(project,entry));setCutoff(entry.date);setNotice('Gasto registrado. El programa aprobado conserva sus valores.');
        }
        if(modal?.kind==='reminder') {const next={...project,reminder:{date:str('date'),text:str('text')}};validateProjects({version:2,projects:[next]});update(next);setNotice('Recordatorio guardado. No modifica importes ni calcula penalizaciones.');}
        if(modal?.kind==='note') {if(!str('note'))throw new Error('Escribe una observación.');update({...project,notes:[...project.notes,str('note')]});setNotice('Observación guardada en esta obra.');}
      }
      setModal(null);
    } catch(e) {setError((e as Error).message);}
  }
  const totals=project?budgetTotals(project):null;
  const metrics=project?projectMetrics(project,cutoff):null;
  const concepts=project?.concepts.filter(c=>`${c.code} ${c.description}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()))||[];
  const capture=project?.concepts.find(c=>c.id===captureConcept);
  const lastCapture=project?.progress.filter(p=>p.conceptId===captureConcept).sort((a,b)=>b.end.localeCompare(a.end))[0];
  const nextCaptureDate=lastCapture?new Date(Date.parse(lastCapture.end)+86400000).toISOString().slice(0,10):project?.start;
  const captureDate=[cutoff,nextCaptureDate||cutoff].sort().at(-1)!;
  const activeMaterial=materials.find(m=>m.id===modal?.concept?.materialId);
  const reminder=project?.reminder||{date:project?.end||'',text:'Revisar el cumplimiento del plazo y los avisos de la dependencia.'};
  const selectedTitle=pages.find(p=>p.id===page)!.label;
  const help:Record<Page,string>={summary:'Comparamos valores acumulados sin IVA. El programa aprobado no cambia con las capturas. El avance se valúa al precio del presupuesto y el gasto se compara en la misma base.',budget:'Los precios se guardan únicamente en esta obra. Cambiar un precio aquí no actualiza otras obras ni el catálogo visual. Al aprobar el programa, el presupuesto original queda fijo; las compras posteriores conservan su propio importe y fecha. El precio puede venir integrado o componerse a partir de un costo directo. El IVA se agrega una sola vez al final. Este presupuesto no es una estimación para cobro.',schedule:'Define cantidades por día para cada concepto. La distribución uniforme es solo una ayuda editable. Al fijar el programa se bloquean catálogo, precios, IVA y calendario. Los adicionales o convenios requieren una regla futura.',progress:'Captura el porcentaje acumulado o la cantidad total ejecutada a la fecha. Pasar de 30 % a 45 % agrega 15 puntos. No se permiten periodos superpuestos, retrocesos ni valores superiores al 100 %. Las correcciones formales quedan por definir.',expenses:'Registra compras y costos incurridos por fecha. El importe sin IVA alimenta la curva roja; el IVA se guarda por separado. La fecha de compra no implica por sí sola una salida de caja o un pago.',review:'Este reporte es un borrador de control. El formato oficial para la dependencia y las estimaciones de cobro se revisarán después. Las penalizaciones son externas; Trazal solo conserva un recordatorio.'};
  const editing=modal?.kind==='tax'&&project?.iva!==null||modal?.kind==='schedule'&&!!project?.start||modal?.kind==='conceptDates'&&!!modal.concept?.start||modal?.kind==='reminder'&&!!project?.reminder||modal?.kind==='daily'&&!!modal.concept?.daily||modal?.kind==='concept'&&!!project?.concepts.some(c=>c.id===modal.concept?.id);
  let formReady=true;
  if(modal?.kind==='daily')formReady=!!daily.length&&daily.every(d=>Number.isFinite(d.quantity)&&d.quantity>=0)&&Math.abs(daily.reduce((sum,d)=>sum+d.quantity,0)-(modal.concept?.quantity||0))<=0.000001;
  if(modal?.kind==='freeze'){try{freezeProject(project);}catch{formReady=false;}}


  if(profileOpen)return <ProfileView profile={profile} onSave={next=>{localStorage.setItem('trazal-profile-v1',JSON.stringify(next));setProfile(next);}} onBack={()=>{setProfileOpen(false);window.scrollTo({top:0,behavior:'instant'});}} backLabel={project?'Volver a la obra':'Volver a mis obras'}/>;
  if(selected==='legacy') return <LegacyApp onWorks={()=>setSelected(null)}/>;
  return <div className="works-app">
    {project&&<aside className="works-sidebar"><button className="brand" onClick={()=>setSelected(null)}><img src="/brand/symbol-mono.svg" alt=""/><span>trazal<small>CONTROL DE OBRA</small></span></button><button className="button works-back" onClick={()=>setSelected(null)}><ArrowLeft size={17}/> Mis obras</button><div className="works-project-name"><strong>{project.name}</strong><span>{project.type}</span></div><nav aria-label="Secciones de la obra">{pages.map(p=><button key={p.id} aria-current={page===p.id?'page':undefined} onClick={()=>go(p.id)}><p.icon size={19}/>{p.label}</button>)}</nav><div className="works-local"><HardDrive size={17}/>{saved?'Guardado en este navegador':'No se pudo guardar. Exporta un respaldo.'}</div></aside>}
    <div className={project?'works-shell':'works-home'}>
      <header className="works-topbar">{project?<span>{project.name} <span className="works-slash">/</span> {selectedTitle}</span>:<img src="/brand/horizontal-mono.svg" alt="Trazal"/>}<div><ThemeSelect/><span className="pill yellow">Mockup · revisión con el ingeniero</span><button className="works-profile-button" onClick={()=>{setProfileOpen(true);window.scrollTo({top:0,behavior:'instant'});}} aria-label="Abrir mi perfil"><span>Bienvenido, <strong>{profile.firstName}</strong></span><span className="works-avatar">{(profile.firstName[0]+(profile.lastName[0]||'')).toLocaleUpperCase()}</span></button></div></header>
      {!project?<main className="works-main works-home-main">
        <div className="works-heading"><div><span className="eyebrow">TU ESPACIO DE TRABAJO</span><h1>Cada obra, en orden.</h1><p>Del catálogo al control diario de avance y gasto.</p></div><button className="button primary" onClick={()=>open('create')}><Plus size={18}/> Crear obra</button></div>
        <div className="works-home-tools"><h2>Mis obras <span>{projects.length}</span></h2><button className="text-button" onClick={exportAll}><Download size={17}/> Respaldar obras</button><button className="text-button" onClick={()=>backup.current?.click()}><Upload size={17}/> Recuperar respaldo</button></div>
        <section className="works-filters" aria-label="Buscar y filtrar obras">
          <div className="works-filter-main">
            <label className="works-search"><Search size={20}/><input aria-label="Buscar obras" placeholder="Buscar obra, alcance o concepto…" value={projectFilters.query} onChange={e=>filterWorks('query',e.target.value)}/>{projectFilters.query&&<button className="icon-button" aria-label="Borrar búsqueda de obras" onClick={()=>filterWorks('query','')}><X size={17}/></button>}</label>
            <label>Tipo de obra<select value={projectFilters.type} onChange={e=>filterWorks('type',e.target.value)}><option value="">Todos los tipos</option>{projectTypes.map(type=><option key={type}>{type}</option>)}</select></label>
            <label>Estado<select value={projectFilters.status} onChange={e=>filterWorks('status',e.target.value)}><option value="">Todos los estados</option><option value="draft">En preparación</option><option value="fixed">Programa fijo</option></select></label>
            <button className="button" aria-expanded={showDates} aria-controls="project-date-filters" onClick={()=>setShowDates(v=>!v)}><CalendarDays size={17}/> Fechas{(projectFilters.from||projectFilters.to)&&<span className="works-filter-dot"/>}</button>
          </div>
          {showDates&&<form key={`${projectFilters.from}-${projectFilters.to}`} id="project-date-filters" className="works-filter-dates" onSubmit={e=>{e.preventDefault();const data=new FormData(e.currentTarget);setProjectFilters(f=>({...f,from:String(data.get("from")||""),to:String(data.get("to")||"")}));}}><div className="title-with-help"><span>Periodo de la obra</span><Help title="Filtrar por periodo">Selecciona las fechas y pulsa Aplicar periodo. Incluye obras cuyo plazo contractual coincida, al menos un día, con ese periodo. Puedes usar solo una fecha. No filtra por fecha de captura.</Help></div><label>Desde<input name="from" type="date" defaultValue={projectFilters.from}/></label><label>Hasta<input name="to" type="date" defaultValue={projectFilters.to}/></label><button className="button" type="submit">Aplicar periodo</button></form>}
          {invalidRange&&<p className="form-error" role="alert">La fecha «Hasta» debe ser igual o posterior a «Desde».</p>}
          <div className="works-filter-bottom"><div className="title-with-help"><span role="status" aria-live="polite">{foundProjects.length} de {projects.length} obras</span><Help title="Búsqueda de obras">Busca por nombre, tipo, dimensiones o alcance, claves y descripciones de conceptos. Ignora mayúsculas y acentos. Puedes combinar la búsqueda con todos los filtros. El caso de referencia se muestra aparte.</Help></div>{filtering&&<button className="text-button" onClick={clearFilters}>Limpiar filtros <X size={15}/></button>}<label>Ordenar por<select value={projectFilters.sort} onChange={e=>filterWorks('sort',e.target.value)}><option value="name">Nombre A–Z</option><option value="end">Fecha de término</option><option value="budget">Mayor presupuesto</option></select></label></div>
        </section>
        {projects.length>0&&foundProjects.length===0&&<section className="panel works-no-results"><Blank>{invalidRange?'Corrige el periodo para consultar las obras.':'No encontramos obras con estos filtros.'}</Blank><button className="button" onClick={clearFilters}>Mostrar todas las obras</button></section>}
        <div className="works-project-grid">{foundProjects.map(p=><button className="works-project-card" key={p.id} onClick={()=>choose(p)}><div className="works-card-top"><FolderOpen size={25}/><span className={`pill ${p.baseline?'olive':'yellow'}`}>{p.baseline?'Programa fijo':'En preparación'}</span></div><h2>{p.name}</h2><p>{p.type}{p.dimensions?` · ${p.dimensions}`:''}</p><strong>{money(budgetTotals(p).total??budgetTotals(p).subtotal)}</strong><div className="works-card-bottom"><span>{p.iva===null?'IVA pendiente · ':''}{p.concepts.length} conceptos · {day(p.end)}</span><ArrowRight size={18}/></div></button>)}</div><button className="works-reference" onClick={()=>setSelected('legacy')}><div className="works-card-top"><Layers size={25}/><span className="pill">Referencia</span></div><h2>Explorar el caso anterior</h2><p>Datos ficticios basados en la estructura de los Excel. Incluye fuentes, flujo y revisión.</p><div className="works-card-bottom"><span>Abrir demo de referencia</span><ArrowRight size={18}/></div></button>
        {!projects.length&&<section className="works-start"><div className="works-step-number">01</div><div><h2>Empieza con el catálogo que te entregan.</h2><p>Crea una obra, agrega sus conceptos y revisa el programa diario antes de fijarlo.</p></div><button className="text-button" onClick={()=>open('create')}>Crear mi primera obra <ArrowRight size={18}/></button></section>}
        <div className="works-home-footer"><HardDrive size={18}/><span>{saved?'Las obras se guardan en este navegador. Puedes exportarlas para conservar una copia.':'No se pudo guardar en este navegador. Descarga un respaldo antes de salir.'}</span><Help title="Almacenamiento del mockup">Este prototipo no sincroniza obras con un servidor. Los datos del navegador pueden borrarse. El respaldo JSON conserva todas tus obras y la recuperación agrega copias.</Help></div>
      </main>:<main className="works-main" id="content">
        <div className="works-heading"><div><span className="eyebrow">{project.type} {project.dimensions&&` / ${project.dimensions}`}</span><div className="title-with-help"><h1>{selectedTitle}</h1><Help title={selectedTitle}>{help[page]}</Help></div></div><div className="works-heading-actions"><span className={`pill ${project.baseline?'olive':'yellow'}`}>{project.baseline?<><LockKeyhole size={13}/> Programa fijo</>:'En preparación'}</span><label className="works-cut">Fecha de corte<input aria-label="Fecha de corte" type="date" min={project.start} value={cutoff} onChange={e=>{if(e.target.value&&e.target.value>=project.start)setCutoff(e.target.value);}}/></label></div></div>

        {page==='summary'&&<>
          {!project.baseline?<section className="works-next"><div><span className="eyebrow">PREPARACIÓN DE LA OBRA</span><h2>{project.concepts.length?'Revisa el programa antes de empezar.':'Todo empieza con tu catálogo.'}</h2><p>{project.concepts.length?`${project.concepts.filter(c=>c.daily).length} de ${project.concepts.length} conceptos tienen distribución diaria.`:'Agrega los conceptos y precios que usarás para presupuestar esta obra.'}</p></div><button className="button primary" onClick={()=>go(project.concepts.length?'schedule':'budget')}>{project.concepts.length?'Revisar programa':'Agregar conceptos'} <ArrowRight size={17}/></button></section>:<>
            <div className="metric-grid"><Metric label="Programa al corte" value={money(metrics!.pv)} help="PV: valor presupuestado de las cantidades programadas hasta esta fecha."/><Metric label="Avance real" value={money(metrics!.ev)} help="EV: porcentaje acumulado de cada concepto por su importe presupuestado, sin IVA."/><Metric label="Gasto real" value={money(metrics!.ac)} help="AC: suma de gastos sin IVA registrados hasta la fecha de corte."/><Metric label="Avance de la obra" value={`${num(metrics!.progress)} %`} help="Avance ponderado por el importe de cada concepto. No es el promedio simple de sus porcentajes."/></div>
            <section className="panel"><div className="panel-heading"><Heading title="Programa, avance y gasto" help="Azul: programa aprobado. Gris: trabajo ejecutado valuado. Rojo: gasto registrado. El plan completo permanece visible; las curvas reales llegan hasta el corte."/></div><Curve project={project} cutoff={cutoff}/></section>
            <div className="works-performance"><section className="panel"><Heading title="¿Cómo va el programa?" help="SPI = avance valuado ÷ programa al corte. Mayor que 1: adelantado; menor que 1: atrasado; igual a 1: conforme al plan. No determina automáticamente penalizaciones."/><strong>{metrics!.spi===null?'Sin programa al corte':metrics!.sv>0?'Adelantado':metrics!.sv<0?'Atrasado':'Conforme al programa'}</strong><p>SPI {metrics!.spi===null?'—':num(metrics!.spi,3)} · Diferencia {money(metrics!.sv)}</p></section><section className="panel"><Heading title="¿Cómo va el gasto?" help="CPI = avance valuado ÷ gasto. Menor que 1: gasto mayor al valor ejecutado; mayor que 1: gasto menor. Comprar material por adelantado puede bajar el índice sin demostrar por sí solo una pérdida definitiva."/><strong>{metrics!.cpi===null?'Sin gasto al corte':metrics!.cv<0?'Gasto mayor al avance':metrics!.cv>0?'Gasto menor al avance':'Gasto igual al avance'}</strong><p>CPI {metrics!.cpi===null?'—':num(metrics!.cpi,3)} · Diferencia {money(metrics!.cv)}</p></section></div>
          </>}
          <section className="works-reminder"><CalendarDays size={22}/><div><Heading title="Recordatorio de plazo" help="Las penalizaciones se gestionan fuera de Trazal. Este aviso solo recuerda revisar el plazo; no calcula ni descuenta importes. Se consulta al abrir la obra, sin notificaciones externas."/><p>{reminder.text}</p><span>{day(reminder.date)}{reminder.date&&cutoff>=reminder.date?" · Revisar al corte":""}</span></div><button className="text-button" onClick={()=>open('reminder')}>Editar recordatorio</button></section>
          <div className="works-shortcuts"><button className="button" onClick={()=>go('progress')}>Registrar avance <ArrowRight size={16}/></button><button className="button" onClick={()=>go('expenses')}>Registrar gasto <ArrowRight size={16}/></button><span>Plazo: {day(project.start)} — {day(project.end)}</span></div>
        </>}

        {page==='budget'&&<>
          <div className="works-toolbar"><label className="search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar clave o concepto" aria-label="Buscar concepto"/></label><div>{!project.baseline&&<><button className="button" onClick={()=>open('materials')}><Layers size={16}/> Materiales y servicios</button><button className="button" onClick={()=>open('catalog')}><Upload size={16}/> Pegar catálogo</button><button className="button primary" onClick={()=>open('concept')}><Plus size={16}/> Nuevo concepto</button></>}<button className="button" onClick={()=>download('Trazal-presupuesto.csv',csv([['Clave','Descripción','Unidad','Cantidad','PU integrado sin IVA','Importe sin IVA'],...project.concepts.map(c=>[c.code,c.description,c.unit,c.quantity,conceptTotal(c)/c.quantity,conceptTotal(c)]),['Subtotal','','','','',totals!.subtotal],[project.iva===null?'IVA pendiente':`IVA ${project.iva}%`,'','','','',totals!.tax??'Por definir'],['Total','','','','',totals!.total??'Por definir']]),'text/csv;charset=utf-8')}><Download size={16}/> CSV</button></div></div>
          <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Clave / concepto</th><th>Unidad</th><th className="num">Cantidad</th><th className="num">P. U. integrado</th><th className="num">Importe sin IVA</th><th/></tr></thead><tbody>{concepts.map(c=><tr key={c.id}><td><div className="material-concept">{materials.find(m=>m.id===c.materialId)&&<img src={materials.find(m=>m.id===c.materialId)!.image} alt=""/>}<div><small>{c.code}</small><strong>{c.description}</strong></div></div></td><td>{c.unit}</td><td className="num">{num(c.quantity,6)}</td><td className="num">{money(conceptTotal(c)/c.quantity)}</td><td className="num">{c.price===0?<span className="pill yellow">Precio pendiente</span>:money(conceptTotal(c))}</td><td><button className="text-button" onClick={()=>open('concept',c)}>{project.baseline?'Ver detalle':'Editar'}</button></td></tr>)}</tbody></table></div>{!concepts.length&&<Blank>{project.concepts.length?'No hay conceptos que coincidan con la búsqueda.':'Agrega un concepto o pega las columnas de tu catálogo de Excel.'}</Blank>}</section>
          <div className="works-budget-bottom"><div><Heading title="Precio e impuestos" help="El precio integrado ya incluye utilidad y cargos. Si partes del costo directo, indirectos, utilidad y otros cargos se calculan sobre ese costo, sin capitalizar entre sí. La fórmula debe validarse con la dependencia. El IVA se aplica al subtotal una sola vez; su tasa es configurable."/>{!project.baseline&&<button className="text-button" onClick={()=>open('tax')}>Ajustar IVA de la obra</button>}</div><div className="works-totals"><span>Valor de la obra <strong>{money(totals!.subtotal)}</strong></span><span>{project.iva===null?'IVA pendiente':`IVA ${num(project.iva)} %`} <strong>{money(totals!.tax)}</strong></span><span>Total <strong>{money(totals!.total)}</strong></span></div></div>
        </>}

        {page==='schedule'&&<>
          <section className="works-program-period"><div><h2>Plazo de la obra</h2><p>{project.start?`${day(project.start)} — ${day(project.end)}`:'Define las fechas para distribuir el trabajo por día.'}</p></div>{!project.baseline&&<button className="button" onClick={()=>open('schedule')}>{project.start?'Editar fechas':'Definir fechas'}</button>}</section>
          <div className="works-toolbar"><Heading title="Programa diario" help="Cada concepto tiene fechas y cantidades por día. La suma diaria debe coincidir con el catálogo. Los días omitidos cuentan como cero. La distribución uniforme usa días naturales y puedes modificarla antes de aprobar."/><div><button className="button" disabled={!project.concepts.some(c=>c.daily)} onClick={()=>download('Trazal-programa-diario.csv',csv([['Obra','Estado','Clave','Concepto','Fecha','Cantidad programada','Unidad','Importe diario sin IVA'],...project.concepts.flatMap(c=>(c.daily||[]).map(d=>[project.name,project.baseline?'Programa fijo':'Borrador',c.code,c.description,d.date,d.quantity,c.unit,conceptTotal(c)*d.quantity/c.quantity]))]),'text/csv;charset=utf-8')}><Download size={16}/> Exportar programa</button>{!project.baseline&&<button className="button primary" onClick={()=>open('freeze')}><LockKeyhole size={17}/> Fijar programa</button>}</div></div>
          <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Concepto</th><th>Inicio</th><th>Término</th><th>Distribución</th><th/></tr></thead><tbody>{project.concepts.map(c=><tr key={c.id}><td><small>{c.code}</small><strong>{c.description}</strong></td><td>{day(c.start)}</td><td>{day(c.end)}{!project.baseline&&project.start&&<button className="text-button" onClick={()=>open('conceptDates',c)}>Editar fechas</button>}</td><td>{c.daily?`${c.daily.length} días · ${num(c.quantity,6)} ${c.unit}`:'Por definir'}</td><td><button className="text-button" disabled={!c.start||!c.end} onClick={()=>open('daily',c)}>{project.baseline?'Ver días':'Programar días'} <ArrowRight size={15}/></button></td></tr>)}</tbody></table></div>{!project.concepts.length&&<Blank>Primero agrega el catálogo en «Catálogo y presupuesto».</Blank>}</section>
          {project.baseline&&<p className="works-caption"><LockKeyhole size={15}/> Aprobado en el mockup el {new Date(project.baseline.approvedAt).toLocaleDateString('es-MX')}. Las capturas de avance y compras conservan este programa.</p>}
        </>}

        {page==='progress'&&<>
          <div className="works-toolbar"><Heading title="Avance por concepto" help="La tabla refleja la fecha de corte. Las capturas posteriores permanecen en el historial. Solo puedes agregar un nuevo periodo después del último registrado en cada concepto."/><button className="button primary" disabled={!project.baseline||project.concepts.every(c=>progressAt(project,c.id,'9999-12-31')===100)} onClick={()=>open('progress')}><Plus size={17}/> Capturar avance</button></div>
          {!project.baseline&&<p className="works-inline-notice">Fija el programa de obra para comenzar a registrar avances.</p>}
          <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Concepto</th><th>Cantidad ejecutada</th><th>Acumulado al corte</th><th className="num">Valor ejecutado</th><th/></tr></thead><tbody>{project.concepts.map(c=>{const pct=progressAt(project,c.id,cutoff);const complete=progressAt(project,c.id,'9999-12-31')===100;return <tr key={c.id}><td><small>{c.code}</small><strong>{c.description}</strong></td><td>{num(c.quantity*pct/100,6)} / {num(c.quantity,6)} {c.unit}</td><td><div className="works-progress-value"><progress max={100} value={pct}/><strong>{num(pct)} %</strong></div></td><td className="num">{money(conceptTotal(c)*pct/100)}</td><td>{complete?<span className="pill olive"><Check size={14}/> Terminado</span>:<button className="text-button" disabled={!project.baseline} onClick={()=>open('progress',c)}>Capturar</button>}</td></tr>;})}</tbody></table></div>{!project.concepts.length&&<Blank>Aquí aparecerán los conceptos del catálogo de esta obra.</Blank>}</section>
          <section className="panel"><div className="panel-heading"><h2>Historial de avances</h2></div>{project.progress.length?[...project.progress].reverse().map(r=><div className="ledger-row" key={r.id}><span><strong>{project.concepts.find(c=>c.id===r.conceptId)?.description}</strong><small>{day(r.start)} — {day(r.end)}{r.end>cutoff?' · Posterior al corte':''}</small></span><strong>{num(r.percent)} % acumulado</strong></div>):<Blank>La primera medición aparecerá aquí.</Blank>}</section>
        </>}

        {page==='expenses'&&<>
          <div className="works-toolbar"><Heading title="Gastos de la obra" help="Puedes asociar un gasto a un concepto o registrarlo como general de la obra. El importe sin IVA es el total de la compra, no el precio por unidad. Cantidad y unidad describen el material comprado."/><button className="button primary" onClick={()=>open('expense')}><Plus size={17}/> Registrar gasto</button></div>
          <div className="works-toolbar"><label>Categoría <select value={expenseCategory} onChange={e=>setExpenseCategory(e.target.value)}><option value="Todas">Todas las categorías</option>{[...new Set([...expenseCategories,...project.expenses.map(e=>e.category)])].map(c=><option key={c}>{c}</option>)}</select></label><span>Subtotales sin IVA al corte · {day(cutoff)}</span></div>
          <div className="works-expense-total">{[...new Set(expenseAtCut.map(e=>e.category))].map(c=><span key={c}>{c}<strong>{money(expenseAtCut.filter(e=>e.category===c).reduce((s,e)=>s+e.amount,0))}</strong></span>)}</div>
          <div className="works-expense-total"><span>Gasto filtrado sin IVA al corte <strong>{money(expenseAtCut.reduce((s,e)=>s+e.amount,0))}</strong></span><span>IVA registrado <strong>{money(expenseAtCut.reduce((s,e)=>s+Math.round(e.amount*e.iva)/100,0))}</strong></span></div>
          <section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Material / gasto</th><th>Concepto</th><th>Cantidad</th><th className="num">Sin IVA</th><th className="num">Con IVA</th></tr></thead><tbody>{[...visibleExpenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=><tr key={e.id}><td>{day(e.date)}{e.date>cutoff&&<small>Posterior al corte</small>}</td><td><strong>{e.label}</strong><small>{e.category}</small></td><td>{project.concepts.find(c=>c.id===e.conceptId)?.description||'General de obra'}</td><td>{e.quantity?`${num(e.quantity,6)} ${e.unit}`:'—'}</td><td className="num">{money(e.amount)}</td><td className="num">{money(e.amount+Math.round(e.amount*e.iva)/100)}</td></tr>)}</tbody></table></div>{!visibleExpenses.length&&<Blank>No hay gastos en esta categoría. Registra servicios, papelería, materiales u otros gastos de esta obra.</Blank>}</section>
        </>}

        {page==='review'&&<>
          <div className="works-toolbar"><Heading title="Reporte para revisión" help="Conserva el corte seleccionado al imprimir. Este es un resumen de control, no un documento autorizado para cobro."/><div><button className="button" onClick={()=>open('note')}><Plus size={16}/> Observación</button><button className="button primary" onClick={()=>window.print()}><Printer size={16}/> Imprimir / PDF</button></div></div>
          <article className="panel works-report"><img src="/brand/horizontal-mono.svg" alt="Trazal"/><span className="eyebrow">BORRADOR DE CONTROL DE OBRA</span><h2>{project.name}</h2><p>{project.type} · {project.dimensions||'Dimensiones sin especificar'}</p><p>Corte: {day(cutoff)} · {project.baseline?'Programa aprobado en el mockup':'Programa en preparación'}</p><div className="works-report-numbers">{[['Presupuesto sin IVA',totals!.subtotal],['IVA',totals!.tax??'Por definir'],['Total',totals!.total??'Por definir'],['Programa al corte',metrics!.pv],['Avance real',metrics!.ev],['Gasto sin IVA',metrics!.ac]].map(([label,value])=><div key={label}><span>{label}</span><strong>{typeof value==='number'?money(value):value}</strong></div>)}</div><p>SPI: {metrics!.spi===null?'Sin base':num(metrics!.spi,3)} · CPI: {metrics!.cpi===null?'Sin base':num(metrics!.cpi,3)} · Avance ponderado: {num(metrics!.progress)} %</p><h3>Observaciones del equipo</h3>{project.notes.length?<ol>{project.notes.map((note,i)=><li key={i}>{note}</li>)}</ol>:<p>Sin observaciones registradas.</p>}<h3>Recordatorio de plazo</h3><p>{day(reminder.date)} · {reminder.text} Penalizaciones gestionadas externamente.</p><h3>Reglas por confirmar</h3><ul><li>Formato de estimaciones para cobro, firmas y entrega a la dependencia.</li><li>Composición de precios, impuestos, indirectos y utilidad.</li><li>Correcciones de avance, conceptos adicionales y convenios de plazo.</li><li>Penalizaciones externas: solo recordatorio de plazo. Las estimaciones de cobro y el control de almacén quedan para otra etapa.</li></ul></article>
        </>}
        <footer className="works-footer"><span><HardDrive size={15}/> Guardado local · {project.concepts.length} conceptos</span><button className="text-button" onClick={exportAll}><Download size={15}/> Respaldar obras</button></footer>
      </main>}
    </div>
    <dialog className={`modal works-modal ${['daily','materials'].includes(modal?.kind||'')?'wide':''}`} ref={dialog} onCancel={()=>setModal(null)} onClick={e=>{if(e.target===e.currentTarget)setModal(null);}}><header><span className="eyebrow">TRAZAL / {modal?.kind==='create'?'NUEVA OBRA':project?.name}</span><button type="button" className="icon-button" aria-label="Cerrar ventana" onClick={()=>setModal(null)}><X size={20}/></button></header>
      {modal&&<ReadyForm key={`${modal.kind}-${modal.concept?.id||''}`} onSubmit={submit} onCancel={()=>setModal(null)} editing={editing} extra={modal.kind==='daily'?JSON.stringify(daily):''} ready={formReady} saveLabel={modal.kind==='freeze'?'Fijar programa':'Guardar'} showSave={!(modal.kind==='materials'||project?.baseline&&['concept','daily'].includes(modal.kind))}>
        {modal.kind!=='materials'&&modal.kind!=='freeze'&&<p className="form-required-note"><Required/> Campos obligatorios</p>}
        {modal.kind==='schedule'&&<><Heading title="Fechas del programa" help="Define el periodo de la obra. Los conceptos sin fechas tomarán este plazo; luego puedes ajustar cada uno. El plazo debe contener todos los conceptos que ya programaste."/><div className="form-grid"><label><span className="field-label">Inicio<Required/></span><input name="start" type="date" defaultValue={project?.start} required/></label><label><span className="field-label">Término<Required/></span><input name="end" type="date" defaultValue={project?.end} required/></label></div></>}
        {modal.kind==='conceptDates'&&<><Heading title="Fechas del concepto" help="Si cambias las fechas, tendrás que revisar y guardar nuevamente la distribución diaria de este concepto."/><p>{modal.concept?.description}</p><div className="form-grid"><label><span className="field-label">Inicio<Required/></span><input name="start" type="date" min={project?.start} max={project?.end} defaultValue={modal.concept?.start||project?.start} required/></label><label><span className="field-label">Término<Required/></span><input name="end" type="date" min={project?.start} max={project?.end} defaultValue={modal.concept?.end||project?.end} required/></label></div></>}

        {modal.kind==='create'&&<><Heading title="Crear una obra" help="Las fechas se definen en Programa de obra. El IVA es opcional aquí: si lo dejas vacío quedará pendiente y podrás configurarlo en el presupuesto."/><label><span className="field-label">Título de la obra<Required/></span><input name="name" required maxLength={140} placeholder="Ej. Construcción de banqueta en calle Reforma" autoFocus/></label><label><span className="field-label">Tipo de obra<Required/></span><select name="type" required defaultValue=""><option value="" disabled>Selecciona un tipo de obra</option>{['Caminos y carreteras','Agua potable','Drenaje','Escuelas','Electrificación','Banquetas y urbanización','Otra obra civil'].map(v=><option key={v}>{v}</option>)}</select></label><label>Dimensiones / alcance (opcional)<input name="dimensions" maxLength={140} placeholder="Ej. 3 km o 250 m²"/></label><label>IVA de la obra (%) (opcional)<input name="iva" type="number" min="0" max="100" step="0.01" placeholder="Por definir"/></label></>}
        {modal.kind==='concept'&&project&&<><Heading title={project.baseline?'Detalle del concepto':project.concepts.some(c=>c.id===modal.concept?.id)?'Editar concepto':'Nuevo concepto'} help="Este precio pertenece solo a esta obra y no cambia los precios de otras obras. El precio integrado ya contempla utilidad y cargos. Usa costo directo solo si necesitas agregarlos explícitamente. El importe se redondea a centavos al terminar la composición. Cantidad vacía = 1; unidad vacía = lote. Puedes dejar el precio pendiente en el borrador y completarlo antes de fijar el programa. No se convierte automáticamente entre kg, metros y piezas."/><>{activeMaterial&&<div className="material-selected"><img src={activeMaterial.image} alt={activeMaterial.name}/><div><span className="pill">{activeMaterial.kind}</span><MaterialCredit material={activeMaterial}/></div></div>}</><fieldset disabled={!!project.baseline}><div className="form-grid"><label><span className="field-label">Clave<Required/></span><input name="code" defaultValue={modal.concept?.code} required maxLength={40}/></label><label>Unidad (opcional)<input name="unit" list="material-units" defaultValue={modal.concept?.unit} placeholder="Sin unidad: lote" maxLength={20}/><datalist id="material-units">{["kg","tonelada","m","m²","m³","pieza","bulto","litro","hora","jornada","lote"].map(u=><option key={u} value={u}/>)}</datalist></label></div><label><span className="field-label">Trabajo a realizar / descripción<Required/></span><input placeholder="Ej. Construcción de banqueta de concreto" name="description" defaultValue={modal.concept?.description} required maxLength={400}/></label><div className="form-grid"><label>Cantidad (opcional)<input name="quantity" type="number" step="any" min="0.000001" defaultValue={modal.concept?.quantity} placeholder="Sin cantidad: 1"/></label><label><span className="field-label">Base del precio<Required/></span><select required name="pricing" value={pricing} onChange={e=>setPricing(e.target.value)}><option value="quoted">Precio integrado sin IVA</option><option value="build">Costo directo + composición</option></select></label></div><label>{pricing==='quoted'?'Precio unitario integrado sin IVA':'Costo directo por unidad'}<input name="price" type="number" step="any" min="0" defaultValue={modal.concept?.price||''} placeholder="Pendiente de cotizar"/></label>{pricing==='build'&&<div className="works-three-fields"><label>Indirectos %<input name="indirect" type="number" min="0" max="100" step="0.01" defaultValue={modal.concept?.indirect||0}/></label><label>Utilidad %<input name="profit" type="number" min="0" max="100" step="0.01" defaultValue={modal.concept?.profit||0}/></label><label>Otros cargos %<input name="charges" type="number" min="0" max="100" step="0.01" defaultValue={modal.concept?.charges||0}/></label></div>}</fieldset>{project.baseline&&<p className="works-inline-notice">Este concepto pertenece al programa aprobado y está bloqueado.</p>}</>}
        {modal.kind==='materials'&&<><Heading title="Materiales y servicios" help="Elige una referencia para agregarla al presupuesto. Cada obra define y conserva su precio, cantidad, unidad y especificaciones. Las fichas comparten solo nombre e imagen: no tienen un precio global ni actualizan presupuestos anteriores. Estas fichas no controlan existencias en almacén. La excavación es un servicio o trabajo."/><div className="materials-grid">{materials.map(material=><article className="material-card" key={material.id}><img src={material.image} alt={material.name}/><div><span className="eyebrow">{material.kind}</span><h3>{material.name}</h3><p>Precio libre · Unidad sugerida: {material.unit}</p><button className="button primary" type="button" onClick={()=>pickMaterial(material)}>Configurar <Plus size={16}/></button><MaterialCredit material={material}/></div></article>)}</div><button className="text-button" type="button" onClick={()=>open('concept')}>Agregar otro material o servicio <Plus size={16}/></button></>}
        {modal.kind==='reminder'&&<><Heading title="Recordatorio de plazo" help="El aviso es informativo. Las penalizaciones son externas y no se incluyen en los cálculos del presupuesto, avance o gasto."/><label><span className="field-label">Fecha de revisión<Required/></span><input name="date" type="date" defaultValue={reminder.date} required/></label><label><span className="field-label">Recordatorio<Required/></span><textarea name="text" rows={3} maxLength={500} defaultValue={reminder.text} required/></label></>}
        {modal.kind==='catalog'&&<><Heading title="Pegar catálogo de Excel" help="Copia cinco columnas en este orden: clave, descripción, unidad, cantidad y precio unitario integrado sin IVA. Se agregan a esta obra. Las claves deben ser únicas y las cantidades no deben tener separadores de miles. No se lee un archivo XLSX en este paso."/><p className="modal-intro">Clave · Descripción · Unidad · Cantidad · Precio sin IVA</p><label><span className="field-label">Filas copiadas de Excel<Required/></span><textarea name="catalog" rows={9} required placeholder={'EXC-01\tExcavación\tm³\t50\t180\nCON-01\tConcreto\tm³\t20\t2500'}/></label></>}
        {modal.kind==='tax'&&<><h2>IVA del presupuesto</h2><label><span className="field-label">Tasa (%)<Required/></span><input name="iva" type="number" min="0" max="100" step="0.01" required defaultValue={project?.iva??''}/></label></>}
        {modal.kind==='daily'&&modal.concept&&<><Heading title="Cantidades por día" help="La suma debe coincidir exactamente con el catálogo (hasta 6 decimales). Puedes usar distribución uniforme y modificarla. Días sin trabajo: cantidad cero. Guardar confirma esta distribución para el concepto."/><p className="modal-intro">{modal.concept.description} · {num(modal.concept.quantity,6)} {modal.concept.unit}</p>{!project?.baseline&&<button className="button" type="button" onClick={()=>{try{setDaily(distributeDaily(modal.concept!.quantity,modal.concept!.start,modal.concept!.end));setDailyFrom(0);setError('');}catch(e){setError((e as Error).message);}}}>Distribuir uniformemente</button>}<div className="works-daily-list">{daily.slice(dailyFrom,dailyFrom+31).map((d,i)=><label className="works-daily-row" key={d.date}><span>{day(d.date)}</span><input aria-label={`Cantidad del ${d.date}`} type="number" min="0" step="any" value={d.quantity} disabled={!!project?.baseline} onChange={e=>setDaily(list=>list.map((v,index)=>index===i+dailyFrom?{...v,quantity:e.target.value===''?0:Number(e.target.value)}:v))}/><span>{modal.concept?.unit}</span></label>)}{!daily.length&&<Blank>Usa «Distribuir uniformemente» para empezar y ajusta las cantidades.</Blank>}</div>{daily.length>31&&<div className="works-toolbar"><button type="button" className="button" disabled={!dailyFrom} onClick={()=>setDailyFrom(v=>v-31)}>Anteriores</button><span>{dailyFrom+1}–{Math.min(dailyFrom+31,daily.length)} de {daily.length} días</span><button type="button" className="button" disabled={dailyFrom+31>=daily.length} onClick={()=>setDailyFrom(v=>v+31)}>Siguientes</button></div>}<p className="works-daily-total">Programado: <strong>{num(daily.reduce((s,d)=>s+d.quantity,0),6)}</strong> / {num(modal.concept.quantity,6)} {modal.concept.unit}</p></>}
        {modal.kind==='freeze'&&<><h2>Fijar el programa de obra</h2><p className="modal-intro">Confirma que el catálogo, presupuesto y cantidades diarias están revisados. Quedarán bloqueados para compararlos con el avance y el gasto.</p><div className="reference-values"><span>Conceptos<strong>{project?.concepts.length}</strong></span><span>Distribución diaria lista<strong>{project?.concepts.filter(c=>c.daily).length} conceptos</strong></span><span>Presupuesto sin IVA<strong>{money(totals!.subtotal)}</strong></span><span>Total con IVA<strong>{money(totals!.total)}</strong></span></div>{!formReady&&<p className="works-inline-notice">Completa fechas, IVA, precios y distribución diaria antes de fijar el programa.</p>}</>}
        {modal.kind==='progress'&&<><Heading title="Capturar avance real" help="Escribe el acumulado total alcanzado, no el incremento. En cantidad, 40 m³ de un catálogo de 100 m³ equivalen a 40 %. Al llegar al 100 % el concepto queda terminado y no admite más capturas."/><label><span className="field-label">Concepto<Required/></span><select name="captureConcept" required value={captureConcept} onChange={e=>setCaptureConcept(e.target.value)}>{project?.concepts.filter(c=>progressAt(project,c.id,'9999-12-31')<100).map(c=><option key={c.id} value={c.id}>{c.code} · {c.description}</option>)}</select></label><p className="works-inline-notice">Último acumulado: {num(lastCapture?.percent||0)} %{lastCapture?` · al ${day(lastCapture.end)}`:''}</p><div className="form-grid"><label><span className="field-label">Desde<Required/></span><input key={`start-${captureConcept}`} name="start" type="date" min={nextCaptureDate} defaultValue={captureDate} required/></label><label><span className="field-label">Hasta<Required/></span><input key={`end-${captureConcept}`} name="end" type="date" min={nextCaptureDate} defaultValue={captureDate} required/></label></div><label><span className="field-label">Forma de captura<Required/></span><select required name="captureMode" value={captureMode} onChange={e=>setCaptureMode(e.target.value)}><option value="percent">Porcentaje acumulado</option><option value="quantity">Cantidad total ejecutada</option></select></label><label><span className="field-label">{captureMode==='percent'?'Acumulado alcanzado (%)':`Cantidad total alcanzada (${capture?.unit||''})`}<Required/></span><input key={`${captureMode}-${captureConcept}`} name="value" type="number" min="0.000001" max={captureMode==='percent'?100:capture?.quantity} step="any" required placeholder={captureMode==='percent'?'Ej. 30':'Ej. 12.5'}/></label></>}
        {modal.kind==='expense'&&<><Heading title="Registrar gasto o compra" help="Captura el importe total sin IVA de la compra. Cantidad y unidad son descriptivas. El gasto alimenta la curva roja en la fecha registrada. No genera por sí mismo avance físico."/><label><span className="field-label">Descripción del gasto<Required/></span><input name="label" required maxLength={200} placeholder="Ej. Pago de servicio topográfico o compra de papelería"/></label><div className="form-grid"><label><span className="field-label">Fecha de compra / costo<Required/></span><input name="date" type="date" defaultValue={cutoff} required/></label><label><span className="field-label">Categoría<Required/></span><select required name="category">{expenseCategories.map(c=><option key={c}>{c}</option>)}</select></label></div><label>Concepto relacionado<select name="concept"><option value="">General de la obra</option>{project?.concepts.map(c=><option value={c.id} key={c.id}>{c.code} · {c.description}</option>)}</select></label><div className="form-grid"><label>Cantidad comprada (opcional)<input name="quantity" type="number" min="0" step="any" placeholder="10"/></label><label>Unidad (opcional)<input name="unit" maxLength={30} placeholder="toneladas, piezas…"/></label></div><div className="form-grid"><label><span className="field-label">Importe total sin IVA<Required/></span><input name="amount" type="number" min="0.01" step="0.01" required/></label><label><span className="field-label">IVA de esta compra (%) · opcional</span><input name="iva" type="number" min="0" max="100" step="0.01" defaultValue="" placeholder="Vacío: 0 %"/></label></div></>}
        {modal.kind==='note'&&<><h2>Anotar acuerdo u observación</h2><label><span className="field-label">Qué necesita cambiar o confirmarse<Required/></span><textarea name="note" rows={6} maxLength={3000} required placeholder="Regla, responsable y ejemplo esperado…"/></label></>}
        {error&&<p className="form-error" role="alert">{error}</p>}
      </ReadyForm>}
    </dialog>
    <input type="file" ref={backup} accept=".json,application/json" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void restoreBackup(file);e.target.value='';}}/>
    {notice&&<div className="toast" role="status"><Check size={17}/>{notice}</div>}
  </div>;
}
